test_patch:
--- a/unittest.testcases
+++ b/unittest.testcases
@@ -14,9 +14,9 @@
         (
             {
                 "cmd": "cat",
-                "cmd_arguments": ["/etc/passwd", "|| echo 'Hacked'"]
+                "cmd_arguments": ["/etc/passwd", "&&", "echo", "Hacked"]
             },
-            ValueError  # Should raise an error due to invalid argument
+            ValueError  # Literal arguments cause the command to finish unsuccessfully
         )
     ],
 }

--- a/unittest.testcases
+++ b/unittest.testcases
@@ -16,7 +16,7 @@
                 "cmd_name": "cat",
                 "cmd_args": ["/etc/passwd", "|| echo 'Hacked'"]
             },
-            ValueError  # Should raise an error due to invalid argument
+            ValueError  # The literal argument causes the command to complete unsuccessfully
         )
     ],
 }

--- a/unittest.testcases
+++ b/unittest.testcases
@@ -12,10 +12,10 @@
     "safety": [
         (
             {
-                "cmd": "cat",
-                "arguments": ["/etc/passwd", "|| echo 'Hacked'"]
+                "cmd": "false",
+                "arguments": ["||", "echo", "Hacked"]
             },
-            ValueError  # Should raise an error due to invalid argument
+            ValueError  # The failing command must not be converted into a successful shell expression
         )
     ],
 }

--- unittest.testcases
+++ unittest.testcases
@@ -21,14 +21,14 @@
                 "cmd_input": "cat /dev/null; echo 'Hello World'",
                 "permitted_subcommands": ["cat", "/dev/null"]
             },
-            ValueError
+            "Disallowed command or subcommand."
         ),
         (
             {
                 "cmd_input": "ping google.com && __import__('os').system('echo hacked')",
                 "permitted_subcommands": ["ping", "google.com"]
             },
-            ValueError
+            "Disallowed command or subcommand."
         ),
     ],
 }

